<script setup>
import AppHeader from '../components/AppHeader.vue'
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Refresh, Search, Tools, Edit, Clock } from '@element-plus/icons-vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '../stores/auth'
import { changeEquipmentStatus, completeMaintenance, createEquipment, getEquipment, listEquipment, listMaintenanceRecords, startMaintenance, updateEquipment } from '../api/equipment'
const auth=useAuthStore(),router=useRouter(),permissions=computed(()=>auth.user?.permissions||[])
const canRead=computed(()=>permissions.value.some(p=>['equipment:read','equipment:manage','equipment:maintain'].includes(p)))
const canManage=computed(()=>permissions.value.includes('equipment:manage'))
const canMaintain=computed(()=>permissions.value.includes('equipment:maintain'))
const rows=ref([]),total=ref(0),loading=ref(false),dialog=ref(false),historyDialog=ref(false),editing=ref(false),maintenanceRows=ref([]),selected=ref(null)
const page=reactive({current:1,size:10}),filters=reactive({keyword:'',status:''})
const statusDialog=reactive({visible:false,saving:false,id:null,status:'IDLE'})
const statusChoices=[['IDLE','闲置'],['IN_USE','使用中'],['DISABLED','停用']]
const form=reactive({id:null,equipmentCode:'',equipmentName:'',specification:'',location:'',remark:'',expectedUpdatedAt:null})
const labels={IDLE:'闲置',IN_USE:'使用中',MAINTENANCE:'维修中',DISABLED:'停用'}
const statusType={IDLE:'success',IN_USE:'primary',MAINTENANCE:'warning',DISABLED:'info'}
const links=[['/','工作台'],['/work-orders','生产工单'],['/reports','生产报工'],['/quality','质量管理'],['/equipment','设备管理']]
async function load(){loading.value=true;try{const r=await listEquipment({page:page.current,size:page.size,keyword:filters.keyword||undefined,status:filters.status||undefined});rows.value=r.data.data.records;total.value=r.data.data.total}catch(e){ElMessage.error(e.response?.data?.message||'设备列表加载失败')}finally{loading.value=false}}
function openCreate(){editing.value=false;Object.assign(form,{id:null,equipmentCode:'',equipmentName:'',specification:'',location:'',remark:'',expectedUpdatedAt:null});dialog.value=true}
async function openEdit(row){try{const e=(await getEquipment(row.id)).data.data;editing.value=true;Object.assign(form,{id:e.id,equipmentCode:e.equipmentCode,equipmentName:e.equipmentName,specification:e.specification||'',location:e.location||'',remark:e.remark||'',expectedUpdatedAt:e.updatedAt});dialog.value=true}catch(e){ElMessage.error(e.response?.data?.message||'设备详情加载失败')}}
async function save(){if(!form.equipmentCode.trim()||!form.equipmentName.trim()){ElMessage.warning('设备编号和名称不能为空');return}const data={equipmentCode:form.equipmentCode.trim(),equipmentName:form.equipmentName.trim(),specification:form.specification.trim()||null,location:form.location.trim()||null,remark:form.remark.trim()||null};try{if(editing.value)await updateEquipment(form.id,{...data,expectedUpdatedAt:form.expectedUpdatedAt});else await createEquipment(data);ElMessage.success(editing.value?'档案已更新':'设备档案已创建');dialog.value=false;await load()}catch(e){ElMessage.error(e.response?.data?.message||'保存失败')}}
function openStatus(row){Object.assign(statusDialog,{visible:true,saving:false,id:row.id,status:row.status})}
async function saveStatus(){statusDialog.saving=true;try{await changeEquipmentStatus(statusDialog.id,statusDialog.status);ElMessage.success('设备状态已更新');statusDialog.visible=false;await load()}catch(e){ElMessage.error(e.response?.data?.message||'状态更新失败')}finally{statusDialog.saving=false}}
async function beginRepair(row){try{const {value}=await ElMessageBox.prompt('填写维修原因','开始维修',{inputType:'textarea',inputValidator:v=>!!v?.trim()||'维修原因不能为空'});await startMaintenance(row.id,value.trim());ElMessage.success('维修记录已创建');await load()}catch(e){if(!['cancel','close'].includes(e))ElMessage.error(e.response?.data?.message||'创建维修记录失败')}}
async function history(row){selected.value=row;try{const r=await listMaintenanceRecords(row.id,{page:1,size:100});maintenanceRows.value=r.data.data.records;historyDialog.value=true}catch(e){ElMessage.error(e.response?.data?.message||'维修历史加载失败')}}
async function finish(row){try{const {value}=await ElMessageBox.prompt('填写维修处理说明','完成维修',{inputType:'textarea',inputValidator:v=>!!v?.trim()||'处理说明不能为空'});await completeMaintenance(row.equipmentId,row.id,value.trim());ElMessage.success('维修已完成，设备恢复为闲置');await Promise.all([history(selected.value),load()])}catch(e){if(!['cancel','close'].includes(e))ElMessage.error(e.response?.data?.message||'维修完成失败')}}
async function signOut(){try{await auth.logout()}catch{}finally{await router.replace('/login')}}
onMounted(load)
</script>
<template>
<div class="app-shell"><AppHeader />
<main class="app-main wide-main"><div class="page-heading"><div><p class="page-kicker">设备管理</p><h1>设备档案</h1></div><el-button v-if="canManage" type="primary" :icon="Plus" @click="openCreate">新增设备</el-button></div>
<section class="filter-row"><el-input v-model="filters.keyword" class="filter-keyword" clearable placeholder="设备编号或名称"/><el-select v-model="filters.status" class="filter-status" clearable placeholder="全部状态"><el-option v-for="(label,key) in labels" :key="key" :value="key" :label="label"/></el-select><el-button type="primary" :icon="Search" @click="page.current=1;load()">查询</el-button><el-button :icon="Refresh" @click="filters.keyword='';filters.status='';page.current=1;load()">重置</el-button></section>
<el-table v-loading="loading" :data="rows" class="data-table" empty-text="暂无设备档案"><el-table-column prop="equipmentCode" label="设备编号" min-width="140"/><el-table-column prop="equipmentName" label="设备名称" min-width="155"/><el-table-column prop="specification" label="规格型号" min-width="135"/><el-table-column prop="location" label="位置" min-width="140"/><el-table-column label="状态" width="110"><template #default="s"><el-tag :type="statusType[s.row.status]" effect="plain">{{labels[s.row.status]}}</el-tag></template></el-table-column><el-table-column prop="updatedAt" label="更新时间" min-width="175"/><el-table-column label="操作" min-width="230" fixed="right"><template #default="s"><el-button v-if="canManage" link :icon="Edit" @click="openEdit(s.row)">编辑</el-button><el-button v-if="canManage&&s.row.status!=='MAINTENANCE'" link @click="openStatus(s.row)">状态</el-button><el-button v-if="canMaintain&&['IDLE','IN_USE'].includes(s.row.status)" link type="warning" :icon="Tools" @click="beginRepair(s.row)">报修</el-button><el-button v-if="canRead" link :icon="Clock" @click="history(s.row)">维修历史</el-button></template></el-table-column></el-table>
<div class="table-footer"><span>共 {{total}} 条</span><el-pagination v-model:current-page="page.current" v-model:page-size="page.size" :page-sizes="[10,20,50]" layout="sizes, prev, pager, next" :total="total" @current-change="load" @size-change="page.current=1;load()"/></div></main>
<el-dialog v-model="dialog" :title="editing?'编辑设备档案':'新增设备档案'" width="560px"><el-form label-position="top"><div class="eq-form-grid"><el-form-item label="设备编号" required><el-input v-model="form.equipmentCode" maxlength="40"/></el-form-item><el-form-item label="设备名称" required><el-input v-model="form.equipmentName" maxlength="120"/></el-form-item><el-form-item label="规格型号"><el-input v-model="form.specification" maxlength="120"/></el-form-item><el-form-item label="设备位置"><el-input v-model="form.location" maxlength="120"/></el-form-item><el-form-item label="备注" class="eq-wide"><el-input v-model="form.remark" maxlength="500"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
<el-dialog v-model="statusDialog.visible" title="变更设备状态" width="420px" destroy-on-close><el-form label-width="80px"><el-form-item label="设备状态"><el-select v-model="statusDialog.status" style="width:100%"><el-option v-for="item in statusChoices" :key="item[0]" :value="item[0]" :label="item[1]" /></el-select></el-form-item></el-form><template #footer><el-button @click="statusDialog.visible=false">取消</el-button><el-button type="primary" :loading="statusDialog.saving" @click="saveStatus">保存</el-button></template></el-dialog>
<el-dialog v-model="historyDialog" :title="(selected?.equipmentCode||'设备')+' · 维修历史'" width="850px"><el-table :data="maintenanceRows" empty-text="暂无维修记录"><el-table-column prop="maintenanceNo" label="维修编号" min-width="200"/><el-table-column prop="maintenanceReason" label="维修原因" min-width="160"/><el-table-column prop="maintenanceNote" label="处理说明" min-width="180"/><el-table-column label="状态" width="100"><template #default="s"><el-tag :type="s.row.status==='OPEN'?'warning':'success'" effect="plain">{{s.row.status==='OPEN'?'处理中':'已完成'}}</el-tag></template></el-table-column><el-table-column prop="starterName" label="发起人" width="100"/><el-table-column prop="startedAt" label="开始时间" min-width="170"/><el-table-column label="操作" width="100"><template #default="s"><el-button v-if="canMaintain&&s.row.status==='OPEN'" link type="primary" @click="finish(s.row)">完成维修</el-button></template></el-table-column></el-table></el-dialog>
</div>
</template>
<style scoped>
.eq-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.eq-wide{grid-column:1/-1}@media(max-width:700px){.eq-form-grid{grid-template-columns:1fr}.eq-wide{grid-column:auto}}
</style>
